script=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gluons — Business Automation Control</title><style>
:root{--bg:#f7f8f5;--white:#ffffff;--ink:#1b2926;--muted:#718079;--brand:#0f7a5b;--brand-soft:#e3f4ec;--border:#e3eae4;--shadow:0 6px 24px rgba(21,58,43,.045)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.48 Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:0}.shell{display:flex;min-height:100vh}.side{width:236px;flex-shrink:0;background:#102722;color:#e9f1eb;padding:24px 16px;display:flex;flex-direction:column;gap:24px}.wordmark{font-size:25px;font-weight:800;letter-spacing:-1px;padding:3px 12px}.wordmark span{color:#7ae2b8}.nav{display:grid;gap:5px}.nav a{color:#a6bab1;text-decoration:none;padding:11px 14px;border-radius:9px;display:block;font-weight:600}.nav a:hover,.nav a.active{background:#234439;color:#e8fff2}.sidefoot{margin-top:auto;border:1px solid #3c5a50;border-radius:12px;padding:13px;color:#b6c7be;font-size:12px}.sidefoot b{color:#fff}.main{padding:28px 42px 60px;flex:1;max-width:1500px;margin:0 auto;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.muted{color:var(--muted)}.eyebrow{font-weight:750;letter-spacing:1.6px;text-transform:uppercase;font-size:10px;color:var(--brand)}h1{font-size:32px;letter-spacing:-1.3px;margin:6px 0}h2{font-size:19px;letter-spacing:-.4px;margin:0}h3{font-size:15px;margin:0}.pill{border-radius:30px;padding:6px 11px;font-size:11px;font-weight:750;background:#eaf3f0;color:#247557;white-space:nowrap}.pill.sim{background:#fff1d7;color:#7b5828}.headerbtn{border:1px solid #dae6dd;background:white;border-radius:9px;padding:9px 12px;color:#365b49;font-weight:600}.hero{background:linear-gradient(115deg,#144935,#0d7256);padding:26px 30px;border-radius:18px;color:white;margin:22px 0;box-shadow:var(--shadow);display:flex;gap:25px;align-items:center;justify-content:space-between}.hero h2{font-size:22px;letter-spacing:-.7px}.hero p{color:#d0e8dd;max-width:660px;margin:7px 0 13px}.hero button{background:#effdf4;color:#0e6044;padding:10px 16px;border-radius:9px;font-weight:750}.badgeHero{background:#ffffff26;border:1px solid #ffffff55;border-radius:11px;padding:10px 13px;font-size:12px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:14px;margin:18px 0 24px}.panel{background:var(--white);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}.kpi{padding:18px}.kpi .num{font-size:27px;font-weight:750;letter-spacing:-1px;margin:8px 0 1px}.kpi .detail{font-size:12px;color:var(--muted)}.row{display:flex;gap:15px}.grow{flex:1;min-width:0}.colside{width:335px;flex-shrink:0}.section-head{display:flex;justify-content:space-between;align-items:center;margin:23px 0 12px;gap:12px}.section-head span{font-size:12px;color:var(--muted)}.task{padding:16px 18px;border-bottom:1px solid var(--border)}.task:last-child{border:0}.task .line{display:flex;justify-content:space-between;align-items:center;gap:12px}.task .name{font-weight:730}.task .desc{color:var(--muted);font-size:12px;margin-top:3px}.task .actions{margin-top:12px;display:flex;gap:7px;flex-wrap:wrap}.mini{background:#f1f5f2;color:#3e5549;padding:7px 10px;border-radius:7px;font-size:11px;font-weight:700}.mini.primary{background:#0f7a5b;color:white}.mini.danger{background:#faeee9;color:#a04e36}.mini:disabled{opacity:.5;cursor:not-allowed}.live{color:#19815a;background:#e8f6ee}.shadow{color:#866d2b;background:#faf3df}.paused{color:#b44b34;background:#fff0e8}.stopped{color:#6d7771;background:#edf0ee}.rightpad{padding:18px}.chat{background:#f1f5f2;border-radius:10px;padding:12px;font-size:13px;margin:12px 0}.reply{background:#e4f2ea;border:1px solid #d0e8d8;padding:12px;border-radius:10px;font-size:12px}.promptrow{display:flex;gap:8px;margin-top:15px}.promptrow input{flex:1;min-width:0;border:1px solid #dce7df;padding:10px;border-radius:8px;outline-color:#0f7a5b}.promptrow button{background:#0f7a5b;color:#fff;font-weight:700;border-radius:8px;padding:9px 12px}.activity{list-style:none;margin:0;padding:0}.activity li{padding:12px 0;border-bottom:1px solid var(--border);font-size:12px}.activity li:last-child{border:0}.activity .tm{font-size:11px;color:var(--muted);display:block;margin-top:2px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.explore{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.skill{padding:15px;min-height:164px;display:flex;flex-direction:column;gap:8px}.skill small{font-weight:700;letter-spacing:.4px;color:#4d9478;text-transform:uppercase}.skill h3{font-size:15px;line-height:1.25}.skill p{margin:0;color:var(--muted);font-size:12px;flex:1}.skill button{align-self:flex-start;background:#eef8f2;color:#13724f;padding:8px 10px;border-radius:7px;font-weight:700;font-size:11px}.toolbar{display:flex;gap:8px;align-items:center}.toolbar input,.toolbar select{border:1px solid var(--border);padding:9px;background:white;border-radius:7px;min-width:0}.toolbar input{width:240px}.notice{background:#fff9e9;border:1px solid #f1e6c9;color:#755a2e;border-radius:9px;padding:10px 12px;font-size:12px;margin:12px 0}.over{font-size:12px;font-weight:600;color:#587265}.screen{scroll-margin-top:15px}.hidden{display:none}.foot{margin-top:28px;text-align:center;font-size:11px;color:#9ea9a1}.stat{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #e4ebe5;font-size:12px}.stat:last-child{border:0}.pad{padding:18px}.modalback{position:fixed;inset:0;background:#12292193;display:none;align-items:center;justify-content:center;padding:15px;z-index:100}.modal{width:min(550px,100%);background:white;border-radius:17px;padding:25px;box-shadow:0 20px 90px #0004}.modal h2{margin-bottom:8px}.field{margin:14px 0}.field label{display:block;font-size:12px;color:#637368;margin-bottom:5px}.field select,.field input{width:100%;border:1px solid #d5e3d7;padding:11px;border-radius:9px}.modalactions{display:flex;justify-content:flex-end;gap:8px}.modalactions button{padding:10px 14px;border-radius:9px;background:#e7ede9;font-weight:750}.modalactions .ok{background:#0f7a5b;color:white}.notify{position:fixed;right:22px;bottom:24px;background:#163e30;color:white;padding:13px 17px;border-radius:10px;max-width:350px;display:none;z-index:110;box-shadow:0 8px 30px #0004}@media(max-width:1110px){.colside{width:270px}.explore{grid-template-columns:repeat(2,1fr)}.side{width:195px}.main{padding:22px}}@media(max-width:820px){.shell{display:block}.side{width:100%;padding:14px;display:block}.nav{display:flex;flex-wrap:wrap}.nav a{padding:7px}.sidefoot{display:none}.main{padding:15px}.kpis{grid-template-columns:repeat(2,1fr)}.row{flex-direction:column}.colside{width:auto}.explore{grid-template-columns:1fr}.hero{flex-direction:column;align-items:flex-start}.toolbar{flex-wrap:wrap}}
</style></head><body><div class="shell"><aside class="side"><div class="wordmark">gluons<span>.</span></div><nav class="nav"><a class="active" href="#overview">◫ &nbsp;Overview</a><a href="#workflows">◇ &nbsp;Automations</a><a href="#discover">✦ &nbsp;Explore skills</a><a href="#activity">◷ &nbsp;Activity</a><a href="#evidence">▣ &nbsp;Proof & ROI</a></nav><div class="sidefoot"><b>Sandbox workspace</b><br>Meridian Distribution (fictional)<br><br>All interactions in this browser prototype are simulated. No external APIs or customer data are connected.</div></aside><main class="main"><header class="top" id="overview"><div><div class="eyebrow">Business command center</div><h1>Good morning, Alex.</h1><span class="muted">Your automations, one place. Your preferred agent, one control layer.</span></div><span class="pill sim">DEMO SIMULATION · NO LIVE INTEGRATIONS</span></header><section class="hero"><div><div class="eyebrow" style="color:#9cf0c6">OPERATIONS COPILOT</div><h2>Automation should feel as natural as a conversation.</h2><p>Discover workflows, run verified trials, approve sensitive actions, and stop any automation—without learning a different platform for every process.</p><button onclick="document.querySelector('#discover').scrollIntoView({behavior:'smooth'})">Explore 31 expert skills →</button></div><div class="badgeHero">CHATGPT · CLAUDE · OPEN SOURCE<br><b>One persistent Gluons task layer</b></div></section><div class="kpis"><div class="panel kpi"><div class="muted">Automations</div><div id="numTasks" class="num">3</div><div class="detail">Active, trial and paused</div></div><div class="panel kpi"><div class="muted">Pending approvals</div><div id="numApprovals" class="num">1</div><div class="detail">Owner signs consequential changes</div></div><div class="panel kpi"><div class="muted">Simulated task events</div><div id="numEvents" class="num">24</div><div class="detail">Audit history retained</div></div><div class="panel kpi"><div class="muted">Sample metered cost</div><div id="demoCost" class="num">$7.42</div><div class="detail">Illustrative only · Not billed</div></div></div><div class="row"><section class="grow screen" id="workflows"><div class="section-head"><h2>Automation control room</h2><span>Start, monitor, pause or cancel</span></div><div class="panel" id="tasklist"></div><div class="notice"><b>Safe control:</b> Pausing stops future steps. Canceling cannot undo messages, calls or orders already completed in an external system.</div><div class="section-head" id="evidence"><h2>Trial proof & ROI</h2><span>Sample metrics, not customer results</span></div><div class="panel pad"><div class="two"><div><div class="over">ORDER EXTRACTION · SHADOW TRIAL</div><h2 style="font-size:31px;margin-top:8px">97.5% <span style="font-size:13px;color:#799188">synthetic accuracy</span></h2><p class="muted">39 / 40 example order drafts matched an artificial test reference. No customer transactions were made.</p></div><div><div class="stat"><span>Sample orders compared</span><b>40</b></div><div class="stat"><span>Unverified estimated time saved</span><b>2.4 hours</b></div><div class="stat"><span>Manual corrections needed</span><b>1</b></div><div class="stat"><span>Actual business ROI</span><b>Not established</b></div></div></div></div></section><aside class="colside"><div class="section-head"><h2>Talk to your agent</h2><span>Illustrative</span></div><div class="panel rightpad"><div class="muted" style="font-size:11px;font-weight:700">YOUR PREFERRED ASSISTANT + GLUONS</div><div class="chat">“Can you try handling our orders without changing our live ERP?”</div><div class="reply" id="chatreply">Absolutely. The <b>Multichannel Order Entry</b> skill supports <b>shadow mode</b>. I can prepare a trial plan, requiring no live writes. Shall I configure it?</div><div class="promptrow"><input id="chatinput" placeholder="Ask to start, pause or view tasks" aria-label="Demo assistant instruction"/><button onclick="chatCommand()">Send</button></div><div style="margin-top:8px;font-size:11px;color:#89978f">Try “pause orders”, “show costs”, or “discover”. Responses are simulated, not an LLM.</div></div><div class="section-head" id="activity"><h2>Activity timeline</h2><span>Auditable events</span></div><div class="panel pad"><ul class="activity" id="activitylist"></ul></div></aside></div><div class="section-head screen" id="discover"><div><h2>Explore expert automation skills</h2><span>31 independently designed workflow specifications</span></div><div class="toolbar"><input id="search" placeholder="Find order, billing, dispatch..." oninput="renderSkills()" aria-label="Search automation skills"/><select id="industry" onchange="renderSkills()" aria-label="Filter industry"><option value="">All industries</option></select></div></div><div id="skills" class="explore"></div><footer class="foot">Gluons product prototype · November 2026 · This local demonstration has zero live integrations, no real customers, and no production task processing.</footer></main></div><div class="modalback" id="modalback"><div class="modal" role="dialog" aria-modal="true"><div class="eyebrow">Configure automation</div><h2 id="modaltitle">Start new trial</h2><p class="muted" id="modaldesc">Select an operating mode.</p><div class="field"><label for="mode">Activation mode</label><select id="mode"><option value="shadow">Shadow (read only, zero side effects)</option><option value="supervised">Supervised (each consequential action requires approval)</option><option value="live">Live (ONLY in a real, production-authorized integration; simulated here)</option></select></div><div class="field"><label for="budget">Monthly cost ceiling (USD, illustration)</label><input id="budget" type="number" value="25" min="0"/></div><p class="notice">This prototype only updates simulated local UI state. It does not collect credentials or call any live provider.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="ok" onclick="addTask()">Create simulated automation</button></div></div></div><div class="notify" id="notification"></div><script id="skills-json" type="application/json">__SKILLS_JSON__</script><script>
const skills=JSON.parse(document.getElementById('skills-json').textContent), state={tasks:[{id:'T-2041',skill:'multichannel_order_entry',name:'Customer order intake',desc:'WhatsApp + email → ERP order drafts',mode:'shadow',status:'Running',events:40},{id:'T-2042',skill:'restaurant_voice_ordering',name:'Inbound telephone ordering',desc:'ElevenLabs calls → approved POS draft',mode:'supervised',status:'Waiting approval',events:11},{id:'T-2043',skill:'home_service_dispatch',name:'Smart dispatch recommendations',desc:'Job queue → technician proposal',mode:'shadow',status:'Paused',events:8}],history:[['Order intake trial evaluated 40 synthetic examples','Just now'],['Telephone order waiting for human approval','3 min ago'],['Dispatch recommendations paused','Yesterday'],['Simulation loaded — no production systems connected','Today']],pending:1,cost:7.42};let chosen=null;function title(id){return id.replace(/_/g,' ').replace(/\b\w/g,l=>l.toUpperCase())};function esc(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')};function notify(msg){const e=document.getElementById('notification');e.textContent=msg;e.style.display='block';clearTimeout(window.__notice);window.__notice=setTimeout(()=>e.style.display='none',3300)}function log(msg){state.history.unshift([msg,'Now (simulation)']);state.history=state.history.slice(0,7);render()};function render(){document.getElementById('numTasks').textContent=state.tasks.filter(x=>x.status!=='Cancelled').length;document.getElementById('numApprovals').textContent=state.tasks.filter(x=>x.status==='Waiting approval').length;document.getElementById('numEvents').textContent=state.tasks.reduce((n,t)=>n+t.events,0);document.getElementById('demoCost').textContent='$'+state.cost.toFixed(2);document.getElementById('tasklist').innerHTML=state.tasks.map(t=>`<div class="task"><div class="line"><div><div class="name">${esc(t.name)} <span class="pill ${t.status==='Running'?(t.mode==='shadow'?'shadow':'live'):t.status==='Paused'?'paused':t.status==='Cancelled'?'stopped':'shadow'}">${esc(t.status)}</span></div><div class="desc">${esc(t.desc)} · ${esc(t.mode)} · ${esc(t.id)}</div></div><div style="font-size:12px;color:#81958a">${t.events} events</div></div><div class="actions"><button class="mini" onclick="changeTask('${t.id}','Running')" ${t.status==='Cancelled'?'disabled':''}>${t.status==='Paused'?'Resume':'View / Resume'}</button><button class="mini" onclick="changeTask('${t.id}','Paused')" ${t.status==='Cancelled'?'disabled':''}>Pause</button><button class="mini danger" onclick="changeTask('${t.id}','Cancelled')" ${t.status==='Cancelled'?'disabled':''}>Cancel</button>${t.status==='Waiting approval'?`<button class="mini primary" onclick="changeTask('${t.id}','Running')">Approve simulated action</button>`:''}</div></div>`).join('');document.getElementById('activitylist').innerHTML=state.history.map(x=>`<li>${esc(x[0])}<span class="tm">${esc(x[1])}</span></li>`).join('')};function changeTask(id,status){const t=state.tasks.find(x=>x.id===id);if(!t)return;if(t.status==='Cancelled'){notify('A canceled task cannot be resumed; create a new run.');return;}t.status=status;t.events+=1;log(t.name+': '+status.toLowerCase()+'.');notify('Simulated state updated. No live systems affected.')};function renderSkills(){const q=(document.getElementById('search').value||'').toLowerCase(),ind=document.getElementById('industry').value;const f=skills.filter(s=>(!ind||s.industry===ind)&&(!q||[s.id,s.industry,s.reference,s.trigger,s.output].join(' ').toLowerCase().includes(q)));document.getElementById('skills').innerHTML=f.map(s=>`<div class="panel skill"><small>${esc(s.industry)} · ${esc(s.risk)} risk</small><h3>${esc(title(s.id))}</h3><p>${esc(s.trigger)} → ${esc(s.output)}</p><button onclick="openModal('${s.id}')">Plan this automation →</button></div>`).join('')||'<p>No matching automation specifications.</p>'};function openModal(id){chosen=skills.find(s=>s.id===id);document.getElementById('modaltitle').textContent=title(id);document.getElementById('modaldesc').textContent=chosen.output;document.getElementById('modalback').style.display='flex'}function closeModal(){document.getElementById('modalback').style.display='none';chosen=null}function addTask(){if(!chosen)return;let md=document.getElementById('mode').value;const id='T-'+(2100+state.tasks.length);state.tasks.push({id,skill:chosen.id,name:title(chosen.id),desc:chosen.output,mode:md,status:'Running',events:0});log(title(chosen.id)+' created in simulated '+md+' mode.');closeModal();document.querySelector('#workflows').scrollIntoView({behavior:'smooth'});notify('Created simulated automation, no API calls made.')};function chatCommand(){let e=document.getElementById('chatinput');const t=e.value.trim().toLowerCase();if(!t)return;const out=document.getElementById('chatreply');if(t.includes('pause')){let task=state.tasks.find(x=>x.status==='Running');if(task){task.status='Paused';task.events++;log('Assistant requested pause on '+task.name+'.');out.textContent='I paused the simulated '+task.name+' task. Queued future actions have been blocked. Any earlier external action would be listed in its receipts.';}else out.textContent='No running tasks to pause in this simulation.'}else if(t.includes('cost'))out.textContent='Current illustrative metered cost is $'+state.cost.toFixed(2)+'. This is fictional demonstration data, not actual vendor spend.';else if(t.includes('discover')||t.includes('automate')){out.textContent='I found 31 expert skill specifications across several industries. Browse the catalog below; every live skill requires approved integrations and tests.';document.querySelector('#discover').scrollIntoView({behavior:'smooth'})}else if(t.includes('approve')){const task=state.tasks.find(x=>x.status==='Waiting approval');if(task){task.status='Running';task.events++;log('Approval granted in demonstration for '+task.name+'.');out.textContent='I recorded a simulated approval. No real order was transmitted.'}else out.textContent='No pending simulated approvals.'}else{out.textContent='I can discover skills, show costs, and simulate task controls. This prototype does not connect to a real LLM or external business systems.'}e.value='';render()};document.getElementById('chatinput').addEventListener('keydown',e=>{if(e.key==='Enter')chatCommand()});document.getElementById('modalback').addEventListener('click',e=>{if(e.target.id==='modalback')closeModal()});const inds=[...new Set(skills.map(s=>s.industry))].sort();document.getElementById('industry').innerHTML+=[...inds].map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');renderSkills();render();
</script></body></html>'''
script=script.replace('__SKILLS_JSON__',json.dumps(catalog).replace('</','<\\/'))
(p/'demo/index.html').write_text(script)
print('demo bytes',(p/'demo/index.html').stat().st_size)
